// Hyphenation, per proofing language: the Liang pattern engine, the US English dictionary and the syllable heuristics.
//
// Translated from wordcraft crates/proof/src/hyphen.rs, patterns.rs, dict.rs, lang.rs (`ProofLang::from_tag`) and vi.rs
// (`looks_vietnamese`) at 0.13.1 (f2dfa0d). MIT, see assets/third-party-licenses/artcraft-reference.txt. The data is wordcraft's
// assets/hyphenation (core/quill/lib/hyphen-data.mjs, generated by scripts/gen-hyphenation.mjs).
//
// English (and every language without patterns of its own): the dictionary (the public-domain Moby Hyphenator II list, ~165k words;
// 's, -s, -es, -ed and -d inflections inherit their stem's breaks), then Liang patterns, then a syllable heuristic. Polish: the exception
// words, the TeX patterns, then a Polish heuristic. Portuguese, Italian and German: their TeX patterns (exceptions first, then the
// generic heuristic). Not translated: Bulgarian, Turkish and Russian syllable rules (bg.rs, tr, ru): those words are not hyphenated.
// Then the paragraph's limits apply. A hyphen goes before the char at each point (char indices into the word).
// No DOM, no Node built-ins.

import {EN_US_PAT, PL_PAT, PT_PAT, IT_PAT, DE_PAT, EN_US_DIC_B64} from './hyphen-data.mjs';
import {inflateRaw} from './inflate.mjs';

export const DOT = '.';
/** Longest pattern kept (patterns.rs MAX_PATTERN_LEN). */
export const MAX_PATTERN_LEN = 20;
const MAX_LETTERS = 61;

/** Hyphenation limits (hyphen.rs `Limits::default`). */
export const defaultLimits = () => ({minWord: 5, afterFirst: 2, beforeLast: 2, capitalized: true});

// ---- Liang patterns ---------------------------------------------------------------------------------------------

export class Patterns {
  constructor() { this.map = new Map(); this.alpha = new Set([DOT]); this.maxLen = 0; this.exceptions = new Map(); }

  /**
   * Parse patterns: whitespace-separated, `%` comments to the end of the line (`#` too at the start of a line). A whole TeX file works:
   * `\patterns{...}` holds patterns and `\hyphenation{...}` exception words written with their hyphens; other commands' arguments are
   * skipped; outside any block a token with a hyphen is an exception and anything else a pattern.
   */
  static parse(text) {
    const p = new Patterns();
    let block = 'patterns';
    for (const raw of text.split('\n')) {
      let line = raw.trim();
      if (line.startsWith('#')) continue;
      line = line.split('%')[0];
      for (let tok of line.split(/\s+/u)) {
        if (!tok) continue;
        if (tok.startsWith('\\')) {
          const cmd = tok.slice(1);
          const brace = cmd.indexOf('{');
          const name = brace < 0 ? cmd : cmd.slice(0, brace);
          block = name === 'hyphenation' ? 'exceptions' : name === 'patterns' ? 'patterns' : cmd.includes('{') ? 'skip' : 'patterns';
          tok = brace < 0 ? '' : cmd.slice(brace + 1);
        }
        const closes = tok.endsWith('}');
        tok = tok.replace(/\}+$/u, '');
        if (tok && block !== 'skip') {
          if (block === 'exceptions' || tok.includes('-')) p.insertException(tok); else p.insert(tok);
        }
        if (closes) block = 'patterns';
      }
    }
    return p;
  }

  intern(c) {
    if (this.alpha.has(c)) return true;
    if (this.alpha.size - 1 >= MAX_LETTERS) return false;
    this.alpha.add(c);
    return true;
  }

  /** Add one pattern like `a1b`; false if it can't be represented. */
  insert(pat) {
    const letters = [];
    const vals = [0];
    for (const c of pat) {
      if (c >= '0' && c <= '9') vals[vals.length - 1] = c.charCodeAt(0) - 48;
      else { if (!this.intern(c)) return false; letters.push(c); vals.push(0); }
    }
    if (!letters.length || letters.length > MAX_PATTERN_LEN) return false;
    this.maxLen = Math.max(this.maxLen, letters.length);
    this.map.set(letters.join(''), Uint8Array.from(vals));
    return true;
  }

  /** Add an exception word written with its hyphens (`ni-gdy`; no hyphen: never broken). */
  insertException(word) {
    let plain = '';
    const points = [];
    let n = 0;
    for (const c of word) {
      if (c === '-') { if (n > 0 && points[points.length - 1] !== n) points.push(n); }
      else { plain += [...c.toLowerCase()].join(''); n++; }
    }
    if (n > 0) this.exceptions.set(plain, points.filter(i => i < n));
  }

  exception(word) { return this.exceptions.get(word) ?? null; }
  get size() { return this.map.size; }
  get empty() { return this.map.size === 0; }

  /** The inter-letter values of a lowercase word (`word` an array of chars): out[i] is the value before char i; null outside the alphabet. */
  values(word) {
    const codes = [DOT];
    for (const c of word) { if (!this.alpha.has(c)) return null; codes.push(c); }
    codes.push(DOT);
    const vals = new Uint8Array(codes.length + 1);
    const top = Math.min(this.maxLen, MAX_PATTERN_LEN);
    for (let s = 0; s < codes.length; s++) {
      let key = '';
      for (let len = 1; len <= top && s + len <= codes.length; len++) {
        key += codes[s + len - 1];
        const v = this.map.get(key);
        if (!v) continue;
        for (let j = 0; j < v.length; j++) if (s + j < vals.length && v[j] > vals[s + j]) vals[s + j] = v[j];
      }
    }
    return Array.from(vals.subarray(1, codes.length));
  }

  /** Break points (char indices, a hyphen goes before that char) of a lowercase word, or null. */
  points(word) {
    const v = this.values(word);
    if (!v) return null;
    const out = [];
    for (let i = 1; i < word.length; i++) if ((v[i] ?? 0) % 2 === 1) out.push(i);
    return out;
  }
}

const lazy = f => { let v = null; return () => (v ??= f()); };
export const patternsEn = lazy(() => Patterns.parse(EN_US_PAT));
export const patternsPl = lazy(() => Patterns.parse(PL_PAT));
export const patternsPt = lazy(() => Patterns.parse(PT_PAT));
export const patternsIt = lazy(() => Patterns.parse(IT_PAT));
export const patternsDe = lazy(() => Patterns.parse(DE_PAT));

// ---- the dictionary -----------------------------------------------------------------------------------------------

const MAGIC = 'DCHYPH1\n';
const MAX_BYTES = 64 << 20;

/** Decode wordcraft's front-coded dictionary (dict.rs `from_bytes`): a Map of lowercase word to its hyphenated form (`-` at each break). */
export function readDictionary(bytes) {
  const raw = inflateRaw(bytes, MAX_BYTES);
  for (let i = 0; i < MAGIC.length; i++) if (raw[i] !== MAGIC.charCodeAt(i)) throw new Error('hyphenation dictionary: bad header');
  // One byte a char, so the front coding (a byte count) works on the string; only the few lines with non-ASCII bytes are decoded as UTF-8.
  let body = '';
  for (let i = MAGIC.length; i < raw.length; i += 8192) body += String.fromCharCode.apply(null, raw.subarray(i, Math.min(raw.length, i + 8192)));
  const map = new Map();
  let cur = '';
  let i = 0;
  while (i < body.length) {
    const p = body.charCodeAt(i);
    const end = body.indexOf(String.fromCharCode(10), i + 1);
    if (end < 0) throw new Error('hyphenation dictionary: truncated');
    if (p > cur.length) throw new Error('hyphenation dictionary: bad prefix');
    cur = cur.slice(0, p) + body.slice(i + 1, end);
    i = end + 1;
    const hyph = /[-ÿ]/.test(cur) ? new TextDecoder().decode(Uint8Array.from(cur, c => c.charCodeAt(0))) : cur;
    map.set(hyph.includes('-') ? hyph.replaceAll('-', '') : hyph, hyph);
  }
  return map;
}

export const dictionaryEn = lazy(() => {
  try {
    const bin = atob(EN_US_DIC_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return readDictionary(bytes);
  } catch { return new Map(); }
});

/** The break points (char indices < 64) a dictionary entry names. */
function dictPoints(hyph, len) {
  const out = [];
  let n = 0;
  for (const c of hyph) { if (c === '-') { if (n > 0 && n < 64 && n < len) out.push(n); } else n++; }
  return out;
}

// ---- languages ---------------------------------------------------------------------------------------------------

/** The proofing language of a BCP 47 tag (lang.rs `from_tag`): en (every English), pl, bg, pt, it, hr, tr, ru, cs, id, es, de, other. */
export function proofLang(tag) {
  const t = String(tag ?? '').trim();
  if (!t) return 'en';
  const primary = t.split(/[-_]/u)[0].toLowerCase();
  const by = {en: 'en', eng: 'en', pl: 'pl', pol: 'pl', bg: 'bg', bul: 'bg', pt: 'pt', por: 'pt', it: 'it', ita: 'it', hr: 'hr', hrv: 'hr', tr: 'tr', tur: 'tr',
    ru: 'ru', rus: 'ru', cs: 'cs', ces: 'cs', cze: 'cs', id: 'id', ind: 'id', in: 'id', es: 'es', spa: 'es', de: 'de', deu: 'de', ger: 'de'};
  return by[primary] ?? 'other';
}

// ---- Vietnamese (no automatic hyphenation: single syllables) ------------------------------------------------------

const vietnameseLetter = c => 'ơƠưƯĩĨũŨ'.includes(c) || (c >= 'Ạ' && c <= 'ỹ') || c === '̉' || c === '̣' || c === '̛';
const combining = c => c >= '̀' && c <= 'ͯ';
/** Is `word` written with a Vietnamese-only letter? */
export function isVietnameseWord(word) {
  const cs = [...word];
  return cs.some(vietnameseLetter) || cs.some((c, i) => i + 1 < cs.length && combining(c) && combining(cs[i + 1]));
}
/** Does a paragraph read as Vietnamese (vi.rs `looks_vietnamese`)? */
export function looksVietnamese(text) {
  let total = 0, marked = 0;
  for (const w of text.split(/[^\p{L}\p{N}̀-ͯ]+/u)) {
    if (!w) continue;
    total++;
    if (isVietnameseWord(w)) marked++;
  }
  return marked > 0 && (marked >= 2 || total <= 3) && marked * 6 >= total;
}

// ---- heuristics --------------------------------------------------------------------------------------------------

const NON_ASCII_CONSONANTS = 'łńśćźżçčďđğģķļľĺňñņřŕšşșťţțžßŋðþ';
const isAlpha = c => /\p{Alphabetic}/u.test(c);
const isUpper = c => /\p{Uppercase}/u.test(c);
const lower1 = c => [...c.toLowerCase()][0] ?? c;
const isAscii = c => c.charCodeAt(0) < 128;
function isVowel(c) {
  const l = lower1(c);
  return isAscii(l) ? 'aeiouy'.includes(l) : isAlpha(l) && !NON_ASCII_CONSONANTS.includes(l);
}
function onsetPair(a0, b0) {
  const a = a0.toLowerCase(), b = b0.toLowerCase();
  return (b === 'h' && 'cstpwg'.includes(a)) || (b === 'r' && 'bcdfgkpt'.includes(a)) || (b === 'l' && 'bcfgkps'.includes(a)) || (a === 'q' && b === 'u') || (a === 's' && 'tpck'.includes(b));
}
const endsWith = (c, ...tail) => c.length >= tail.length && tail.every((t, i) => c[c.length - tail.length + i] === t);

/** Syllable heuristic: V-CV ("ty-po"), VC-CV ("hap-pen"), keeping onset clusters ("gra-phy"). */
function heuristicPoints(c) {
  const n = c.length;
  if (n < 4 || !c.every(isAlpha)) return [];
  const v = c.map(isVowel);
  const end = i => (n - i >= 2 && (endsWith(c, 'e', 'd') || endsWith(c, 'e', 's')) ? n - 2 : endsWith(c, 'e') ? n - 1 : n);
  const bytes = [];
  const enc = new TextEncoder();
  let acc = 0;
  for (const ch of c) { bytes.push(acc); acc += enc.encode(ch).length; }
  bytes.push(acc);
  const nextVowel = new Array(n + 1).fill(n);
  for (let i = n - 1; i >= 0; i--) nextVowel[i] = v[i] ? i : nextVowel[i + 1];
  const out = [];
  let vowelBefore = false;
  for (let i = 1; i < n; i++) {
    vowelBefore ||= v[i - 1];
    let ok;
    if (v[i - 1] && !v[i]) ok = (i + 1 < n && v[i + 1]) || (i + 2 < n && onsetPair(c[i], c[i + 1]) && v[i + 2]);
    else if (!v[i - 1] && !v[i]) ok = (i >= 2 && v[i - 2] && i + 1 < n && v[i + 1] && !onsetPair(c[i - 1], c[i]) && c[i - 1] !== c[i]) || (c[i - 1] === c[i] && i >= 2 && v[i - 2]);
    else ok = false;
    const e = end(i);
    if (ok && nextVowel[i] < e && bytes[e] - bytes[i] > 1 && vowelBefore) out.push(i);
  }
  return out;
}

const isDigraphPl = (a, b) => (a === 'c' && (b === 'h' || b === 'z')) || (a === 'd' && 'zźż'.includes(b)) || ((a === 'r' || a === 's') && b === 'z');

/** Polish syllable heuristic, for words with letters outside the Polish pattern alphabet. */
function heuristicPointsPl(c) {
  const n = c.length;
  if (n < 4 || !c.every(isAlpha)) return [];
  const v = c.map(isVowel);
  const at = i => v[i] ?? false;
  const nucleus = c.map((ch, i) => at(i) && !(ch === 'i' && i > 0 && !at(i - 1) && at(i + 1)));
  const nuclei = [];
  nucleus.forEach((x, i) => { if (x) nuclei.push(i); });
  const out = [];
  for (let k = 0; k + 1 < nuclei.length; k++) {
    const a = nuclei[k], b = nuclei[k + 1];
    const start = a + 1, end = b;
    if (start >= end) continue;
    const units = [];
    let i = start;
    while (i < end) {
      units.push(i);
      i += i + 1 < end && c[i] !== undefined && c[i + 1] !== undefined && isDigraphPl(c[i], c[i + 1]) ? 2 : 1;
      if (i < end && c[i] === 'i') i++;
    }
    const sonorant = j => 'lłmnńrj'.includes(c[j] ?? '#');
    const firstIsSingle = units[1] !== undefined && units[1] === start + 1;
    const doubled = c[start] !== undefined && c[start + 1] === c[start];
    out.push(units.length >= 2 && firstIsSingle && (sonorant(start) || doubled) ? start + 1 : start);
  }
  return out;
}

// ---- word breaks -------------------------------------------------------------------------------------------------

const isApostrophe = c => c === "'" || c === '’' || c === 'ʼ';
const isWordChar = c => isAlpha(c) || isApostrophe(c);

function coreBreaksPatterns(pats, core) {
  const s = core.join('');
  const ex = pats.exception(s);
  if (ex) return [[...ex], 'dictionary'];
  if (!pats.empty) { const p = pats.points(core); if (p) return [p, 'patterns']; }
  return [heuristicPoints(core), 'heuristic'];
}

/** Unrestricted break points of one lowercase core (letters and `'` only) in `lang`: [points, source]. */
function coreBreaks(core, lang) {
  const n = core.length;
  if (n < 2) return [[], 'none'];
  if (lang === 'pl') {
    const pats = patternsPl();
    const ex = pats.exception(core.join(''));
    if (ex) return [[...ex], 'dictionary'];
    if (!pats.empty) { const p = pats.points(core); if (p) return [p, 'patterns']; }
    return [heuristicPointsPl(core), 'heuristic'];
  }
  // Bulgarian, Turkish and Russian have syllable rules upstream (not translated here): their words are left alone.
  if (lang === 'bg' || lang === 'tr' || lang === 'ru') return [[], 'none'];
  if (lang === 'pt') return coreBreaksPatterns(patternsPt(), core);
  if (lang === 'it') return coreBreaksPatterns(patternsIt(), core);
  if (lang === 'de') return coreBreaksPatterns(patternsDe(), core);
  const dict = dictionaryEn();
  const s = core.join('');
  const hit = dict.get(s);
  if (hit) return [dictPoints(hit, n), 'dictionary'];
  // Inflections inherit the stem's breaks (the suffix adds no break of its own).
  for (const suf of ["'s", 's', 'es', 'ed', 'd']) {
    if (s.endsWith(suf)) {
      const stem = s.slice(0, s.length - suf.length);
      const len = [...stem].length;
      const h = len >= 2 ? dict.get(stem) : null;
      if (h) return [dictPoints(h, len), 'dictionary'];
    }
  }
  const pats = patternsEn();
  if (!pats.empty) { const p = pats.points(core); if (p) return [p, 'patterns']; }
  return [heuristicPoints(core), 'heuristic'];
}

/**
 * Unrestricted break points of `word` in `lang` (char indices; a hyphen goes before that char): case, apostrophes (`don't`), surrounding
 * punctuation and compounds (each letter run is hyphenated separately). No break is placed next to an apostrophe or a non-letter.
 * Returns [points, source].
 */
export function wordBreaks(word, lang = 'en') {
  const chars = [...word];
  const out = [];
  let src = 'none';
  let i = 0;
  while (i < chars.length) {
    if (!isWordChar(chars[i])) { i++; continue; }
    let j = i;
    while (j < chars.length && isWordChar(chars[j])) j++;
    let a = i, b = j;
    while (a < b && isApostrophe(chars[a])) a++;
    while (b > a && isApostrophe(chars[b - 1])) b--;
    const core = chars.slice(a, b).map(c => (isApostrophe(c) ? "'" : lower1(c)));
    const [pts, s] = coreBreaks(core, lang);
    if (src === 'none') src = s;
    for (const p of pts) if (p > 0 && p < core.length && core[p - 1] !== "'" && core[p] !== "'") out.push(a + p);
    i = j;
  }
  return [out, src];
}

/** Allowed hyphenation points in `word`, a word in `lang`, with the paragraph limits applied to each letter run (hyphen_points_in). */
export function hyphenPoints(word, lim = defaultLimits(), lang = 'en') {
  const chars = [...word];
  const [pts] = wordBreaks(word, lang);
  if (!pts.length) return pts;
  const minBefore = Math.max(lim.afterFirst, 1), minAfter = Math.max(lim.beforeLast, 1);
  const letters = [], upper = [];
  let l = 0, u = 0;
  for (const c of chars) { letters.push(l); upper.push(u); if (isAlpha(c)) { l++; if (isUpper(c)) u++; } }
  letters.push(l); upper.push(u);
  const runOf = new Array(chars.length).fill(null);
  for (let i = 0; i < chars.length;) {
    let j = i;
    while (j < chars.length && isWordChar(chars[j])) j++;
    let a = i, b = j;
    while (a < b && isApostrophe(chars[a])) a++;
    while (b > a && isApostrophe(chars[b - 1])) b--;
    for (let k = i; k < j; k++) runOf[k] = [a, b];
    i = Math.max(j, i + 1);
  }
  const count = (v, a, b) => Math.max(0, (v[b] ?? 0) - (v[a] ?? 0));
  return pts.filter(p => {
    const run = runOf[p];
    if (!run) return false;
    const [a, b] = run;
    const n = count(letters, a, b);
    if (n < Math.max(lim.minWord, 2)) return false;
    if (n > 1 && count(upper, a, b) === n) return false;
    if (!lim.capitalized && chars[a] !== undefined && isUpper(chars[a])) return false;
    return count(letters, a, p) >= minBefore && count(letters, p, b) >= minAfter;
  });
}

/** `word` with `-` at every hyphenation point (tests and diagnostics). */
export function hyphenateWord(word, lim = defaultLimits(), lang = 'en') {
  const pts = new Set(hyphenPoints(word, lim, lang));
  return [...word].map((c, i) => (pts.has(i) ? '-' + c : c)).join('');
}
